solution:
use xiom.io;

fn operation_a() -> Result[Str, Str] {
  return Err("A failed");
}

fn operation_b() -> Result[Str, Str] {
  return Err("B failed");
}

fn operation_c() -> Result[Str, Str] {
  return Ok("C succeeded");
}

fn try_all() -> Result[Str, Str] {
  if let Ok(val) = operation_a() {
    return Ok(val);
  }
  if let Ok(val) = operation_b() {
    return Ok(val);
  }
  if let Ok(val) = operation_c() {
    return Ok(val);
  }
  return Err("All operations failed");
}

fn main() -> Int {
  match try_all() {
    Ok(_) => { return 200; }
    Err(_) => { return 500; }
  }
}
